import { createState, collectCoin } from '../logic/score.js';

export class GameScene extends Phaser.Scene {
  constructor() {
    super('game');
    this.state = createState();
  }

  create() {
    this.player = this.add.rectangle(400, 300, 24, 24, 0xffcc00);
    this.physics.add.existing(this.player);
    this.coins = this.physics.add.group();
    for (let i = 0; i < 8; i++) this.coins.add(this.add.circle(80 + i * 90, 120, 8, 0xffffff));
    this.scoreText = this.add.text(16, 16, `Score: ${this.state.score}`, {
      fontFamily: 'monospace',
      fontSize: '24px',
      color: '#ffffff',
    });
    this.physics.add.overlap(this.player, this.coins, (_player, coin) => {
      coin.destroy();
      this.state = collectCoin(this.state);
      this.scoreText.setText(`Score: ${this.state.score}`);
    });
    this.cursors = this.input.keyboard.createCursorKeys();
  }

  update() {
    const speed = 200;
    const body = this.player.body;
    body.setVelocity(0);
    if (this.cursors.left.isDown) body.setVelocityX(-speed);
    if (this.cursors.right.isDown) body.setVelocityX(speed);
    if (this.cursors.up.isDown) body.setVelocityY(-speed);
    if (this.cursors.down.isDown) body.setVelocityY(speed);
  }
}
